import{_ as t,o,c as r,a5 as a}from"./chunks/framework.BPFk9-tb.js";const d=JSON.parse('{"title":"写作课作业-026","description":"","frontmatter":{"date":"2020-08-14T20:20:29","title":"写作课作业-026","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/026.md","filePath":"posts/homework/026.md"}'),p={name:"posts/homework/026.md"};function s(_,e,i,n,c,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<blockquote><p>学习“习得性无助”这个概念，结合工作和生活经济来谈谈如何识别和避免“习得性无助”的危害。</p></blockquote><p>习得性无助是指人或动物接连不断的受到挫折，便会感到自己对于一切都无能为力，丧失信心，陷入一种无助的心理状态。习得无助感的理论，最早是在1975年由<a href="https://zh.wikipedia.org/wiki/%E8%B3%93%E5%B7%9E%E5%A4%A7%E5%AD%B8" target="_blank" rel="noreferrer">宾州大学</a>心理系的教授<a href="https://zh.wikipedia.org/wiki/%E9%A9%AC%E4%B8%81%C2%B7%E8%B5%9B%E9%87%8C%E6%A0%BC%E6%9B%BC" target="_blank" rel="noreferrer">马丁·赛里格曼</a>所完成的。</p><p>如果说狗遭受电击后躺着不动而不是尝试逃跑，因为电看不见摸不着，算是情有可原的话，那庞然大物的大象没有跨过那个矮桩，就让人震惊了。但我们经历习得性无助的时候而不自知的时候，应该怎么办呢？</p><blockquote><p>听到XXX，我就头疼。</p><p>看到XXX，我就想睡觉。</p></blockquote><p>产生“习得性无助”时，就像操作系统发生死锁，需要打破循环等待条件才能解锁，承认自己不能做到某件事，但不要把问题扩大化，不要因为这件事情而否定自己。以前新人来的时候，一般会对他说，如果碰到一个问题自己处理了半天也没有搞定，就需要求助，就要问了，不能在自己一个人蒙着头的搞了。也是为了避免新人多次碰到问题而受打击，认为自己不适合开发。</p><p>习得性无助是把自己框在了一个悲观的框架里，我们可以调整我的思考框架或者常用语来把自己引导到一个积极的框架当中。自己编程时有个习惯，一开始我也不知道，是我同事告诉我的，他说你怎么没事在笑呢，想了想我刚才是碰到问题了。</p>',6)])])}const E=t(p,[["render",s]]);export{d as __pageData,E as default};
